{
  "root": "main_stack",
  "state": {
    "context_details": [
      {
        "label": "Travelers",
        "value": "Two adults"
      },
      {
        "label": "Vehicle",
        "value": "Rental car (assumed)"
      },
      {
        "label": "Time of Year",
        "value": "October 2024 (expect mild temperatures, potential for coastal fog in mornings, generally clear afternoons)"
      },
      {
        "label": "Road Conditions",
        "value": "Highway 1 through Big Sur is assumed to be open. Always check current road conditions before departure."
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_text",
        "intro_text",
        "itinerary_h2",
        "context_h3",
        "context_table",
        "day1_card",
        "day2_card",
        "day3_card",
        "day4_card",
        "day5_card",
        "quick_actions_h2",
        "quick_actions_stack",
        "sources_h2",
        "sources_stack"
      ]
    },
    "title_text": {
      "type": "Text",
      "props": {
        "text": "California Coast Road Trip: San Francisco to Los Angeles",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This 5-day itinerary guides two adults on a scenic drive down California's iconic Highway 1, blending breathtaking coastal views with charming towns and cultural stops. October offers pleasant weather, fewer crowds than peak summer, and often clear skies for stunning vistas."
      },
      "children": []
    },
    "itinerary_h2": {
      "type": "Text",
      "props": {
        "text": "5-Day Coastal Journey Itinerary",
        "variant": "h2"
      },
      "children": []
    },
    "context_h3": {
      "type": "Text",
      "props": {
        "text": "Context for Your Trip",
        "variant": "h3"
      },
      "children": []
    },
    "context_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "label",
            "label": "Detail"
          },
          {
            "key": "value",
            "label": "Description"
          }
        ],
        "statePath": "/context_details",
        "domain": "generic",
        "preferredPresentation": "cards"
      },
      "children": []
    },
    "day1_card": {
      "type": "Card",
      "props": {},
      "children": [
        "day1_header_stack",
        "day1_morning_text",
        "day1_afternoon_text",
        "day1_food_text",
        "day1_overnight_text",
        "day1_driving_text"
      ]
    },
    "day1_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "day1_icon",
        "day1_title"
      ]
    },
    "day1_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000244_01_2_car-front.svg"
      },
      "children": []
    },
    "day1_title": {
      "type": "Text",
      "props": {
        "text": "Day 1: San Francisco to Monterey Peninsula",
        "variant": "h3"
      },
      "children": []
    },
    "day1_morning_text": {
      "type": "Text",
      "props": {
        "text": "Morning: Depart San Francisco, taking a moment to appreciate the Golden Gate Bridge. Head south on scenic Highway 1, enjoying views of the Pacific Ocean. Consider a brief stop in Half Moon Bay for coffee or a walk on the beach."
      },
      "children": []
    },
    "day1_afternoon_text": {
      "type": "Text",
      "props": {
        "text": "Afternoon: Continue to Santa Cruz, perhaps visiting the historic Boardwalk or the natural beauty of Natural Bridges State Beach. Arrive in Monterey, explore Cannery Row, and visit the renowned Monterey Bay Aquarium."
      },
      "children": []
    },
    "day1_food_text": {
      "type": "Text",
      "props": {
        "text": "Food: Fresh seafood dinner at a restaurant overlooking Monterey Bay."
      },
      "children": []
    },
    "day1_overnight_text": {
      "type": "Text",
      "props": {
        "text": "Overnight: Monterey or the charming nearby town of Carmel-by-the-Sea."
      },
      "children": []
    },
    "day1_driving_text": {
      "type": "Text",
      "props": {
        "text": "Approx. Driving Time: 2.5 - 3 hours (without stops)"
      },
      "children": []
    },
    "day2_card": {
      "type": "Card",
      "props": {},
      "children": [
        "day2_header_stack",
        "day2_morning_text",
        "day2_afternoon_text",
        "day2_food_text",
        "day2_overnight_text",
        "day2_driving_text"
      ]
    },
    "day2_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "day2_icon",
        "day2_title"
      ]
    },
    "day2_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000241_01_8_signpost-split.svg"
      },
      "children": []
    },
    "day2_title": {
      "type": "Text",
      "props": {
        "text": "Day 2: Monterey Peninsula through Big Sur to San Simeon",
        "variant": "h3"
      },
      "children": []
    },
    "day2_morning_text": {
      "type": "Text",
      "props": {
        "text": "Morning: If staying in Carmel, drive the picturesque 17-Mile Drive (toll required) through Pebble Beach. Then, embark on the legendary drive through Big Sur, stopping at iconic viewpoints like Bixby Bridge and Pfeiffer Beach (known for purple sand, requires advance reservation and difficult access)."
      },
      "children": []
    },
    "day2_afternoon_text": {
      "type": "Text",
      "props": {
        "text": "Afternoon: Continue south, making sure to stop at Julia Pfeiffer Burns State Park for views of McWay Falls, a stunning waterfall cascading onto the beach. The drive through Big Sur is slow and winding, so allow ample time for photos and enjoyment."
      },
      "children": []
    },
    "day2_food_text": {
      "type": "Text",
      "props": {
        "text": "Food: Pack a picnic to enjoy at a scenic Big Sur overlook, or grab a casual meal in Cambria or San Simeon upon arrival."
      },
      "children": []
    },
    "day2_overnight_text": {
      "type": "Text",
      "props": {
        "text": "Overnight: San Simeon or Cambria, located just south of Big Sur."
      },
      "children": []
    },
    "day2_driving_text": {
      "type": "Text",
      "props": {
        "text": "Approx. Driving Time: 3 - 4 hours (very scenic, plan for many stops)"
      },
      "children": []
    },
    "day3_card": {
      "type": "Card",
      "props": {},
      "children": [
        "day3_header_stack",
        "day3_morning_text",
        "day3_afternoon_text",
        "day3_food_text",
        "day3_overnight_text",
        "day3_driving_text"
      ]
    },
    "day3_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "day3_icon",
        "day3_title"
      ]
    },
    "day3_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000242_01_2_house.svg"
      },
      "children": []
    },
    "day3_title": {
      "type": "Text",
      "props": {
        "text": "Day 3: San Simeon to Santa Barbara",
        "variant": "h3"
      },
      "children": []
    },
    "day3_morning_text": {
      "type": "Text",
      "props": {
        "text": "Morning: Begin with a tour of Hearst Castle (advance reservations highly recommended). After, continue south on Highway 1, which eventually merges into US-101."
      },
      "children": []
    },
    "day3_afternoon_text": {
      "type": "Text",
      "props": {
        "text": "Afternoon: Stop in Morro Bay to see the iconic Morro Rock, or enjoy the sandy beaches of Pismo Beach. Consider a detour to Solvang, a unique Danish-themed village, for a taste of Europe in California. Arrive in Santa Barbara."
      },
      "children": []
    },
    "day3_food_text": {
      "type": "Text",
      "props": {
        "text": "Food: Enjoy dinner in Santa Barbara, known for its excellent Californian cuisine and wine."
      },
      "children": []
    },
    "day3_overnight_text": {
      "type": "Text",
      "props": {
        "text": "Overnight: Santa Barbara."
      },
      "children": []
    },
    "day3_driving_text": {
      "type": "Text",
      "props": {
        "text": "Approx. Driving Time: 3.5 - 4.5 hours (without stops)"
      },
      "children": []
    },
    "day4_card": {
      "type": "Card",
      "props": {},
      "children": [
        "day4_header_stack",
        "day4_morning_text",
        "day4_afternoon_text",
        "day4_food_text",
        "day4_overnight_text",
        "day4_driving_text"
      ]
    },
    "day4_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "day4_icon",
        "day4_title"
      ]
    },
    "day4_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000241_01_10_geo-alt.svg"
      },
      "children": []
    },
    "day4_title": {
      "type": "Text",
      "props": {
        "text": "Day 4: Santa Barbara to Santa Monica",
        "variant": "h3"
      },
      "children": []
    },
    "day4_morning_text": {
      "type": "Text",
      "props": {
        "text": "Morning: Explore Santa Barbara's charming downtown, visit the historic Mission Santa Barbara, or stroll along Stearns Wharf. Depart south on US-101, transitioning back to scenic Highway 1 as you approach Los Angeles County."
      },
      "children": []
    },
    "day4_afternoon_text": {
      "type": "Text",
      "props": {
        "text": "Afternoon: Drive through the beautiful coastal towns of Malibu, perhaps stopping at Zuma Beach or the Malibu Pier. Arrive in Santa Monica, where you can relax on the beach, explore the Santa Monica Pier, and shop along the 3rd Street Promenade."
      },
      "children": []
    },
    "day4_food_text": {
      "type": "Text",
      "props": {
        "text": "Food: Casual dinner at one of Santa Monica's many restaurants, from beachfront cafes to upscale dining."
      },
      "children": []
    },
    "day4_overnight_text": {
      "type": "Text",
      "props": {
        "text": "Overnight: Santa Monica."
      },
      "children": []
    },
    "day4_driving_text": {
      "type": "Text",
      "props": {
        "text": "Approx. Driving Time: 2 - 3 hours (can be longer with LA traffic)"
      },
      "children": []
    },
    "day5_card": {
      "type": "Card",
      "props": {},
      "children": [
        "day5_header_stack",
        "day5_morning_text",
        "day5_afternoon_text",
        "day5_food_text",
        "day5_overnight_text",
        "day5_driving_text"
      ]
    },
    "day5_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "day5_icon",
        "day5_title"
      ]
    },
    "day5_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000244_01_9_map.svg"
      },
      "children": []
    },
    "day5_title": {
      "type": "Text",
      "props": {
        "text": "Day 5: Los Angeles Exploration",
        "variant": "h3"
      },
      "children": []
    },
    "day5_morning_text": {
      "type": "Text",
      "props": {
        "text": "Morning: Spend the morning exploring a classic Los Angeles landmark. Options include hiking to the Griffith Observatory for panoramic city views and a look at the Hollywood Sign, or visiting the Hollywood Walk of Fame and TCL Chinese Theatre."
      },
      "children": []
    },
    "day5_afternoon_text": {
      "type": "Text",
      "props": {
        "text": "Afternoon: Depending on your interests, consider a visit to the Getty Center for art and architecture, stroll through Beverly Hills and Rodeo Drive, or relax at Venice Beach to experience its vibrant boardwalk culture."
      },
      "children": []
    },
    "day5_food_text": {
      "type": "Text",
      "props": {
        "text": "Food: A farewell dinner in Los Angeles, choosing from its incredibly diverse culinary scene."
      },
      "children": []
    },
    "day5_overnight_text": {
      "type": "Text",
      "props": {
        "text": "Overnight: Los Angeles (end of road trip)."
      },
      "children": []
    },
    "day5_driving_text": {
      "type": "Text",
      "props": {
        "text": "Approx. Driving Time: Varies greatly depending on LA traffic and chosen activities."
      },
      "children": []
    },
    "quick_actions_h2": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "button_car_rental",
        "button_road_conditions",
        "button_accommodations"
      ]
    },
    "button_car_rental": {
      "type": "Button",
      "props": {
        "label": "Find Rental Cars"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.kayak.com/cars"
          }
        }
      },
      "children": []
    },
    "button_road_conditions": {
      "type": "Button",
      "props": {
        "label": "Caltrans Road Info"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://roads.dot.ca.gov/"
          }
        }
      },
      "children": []
    },
    "button_accommodations": {
      "type": "Button",
      "props": {
        "label": "Book Hotels"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.booking.com/region/us/california.html"
          }
        }
      },
      "children": []
    },
    "sources_h2": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "button_california_tourism",
        "button_monterey_aquarium",
        "button_hearst_castle",
        "button_griffith_observatory"
      ]
    },
    "button_california_tourism": {
      "type": "Button",
      "props": {
        "label": "California Tourism Information"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.visitcalifornia.com/"
          }
        }
      },
      "children": []
    },
    "button_monterey_aquarium": {
      "type": "Button",
      "props": {
        "label": "Monterey Bay Aquarium"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.montereybayaquarium.org/"
          }
        }
      },
      "children": []
    },
    "button_hearst_castle": {
      "type": "Button",
      "props": {
        "label": "Hearst Castle Reservations"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://hearstcastle.org/"
          }
        }
      },
      "children": []
    },
    "button_griffith_observatory": {
      "type": "Button",
      "props": {
        "label": "Griffith Observatory"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://griffithobservatory.org/"
          }
        }
      },
      "children": []
    }
  }
}
